async function loadUser(id: string) {
  const res = await fetch(`/api/users/${id}`)
  if (!res.ok) throw new Error('failed')
  return await res.json()
}

// 呼ぶ側
loadUser('1').then(u => console.log(u)).catch(e => console.error(e))

// ❌ 直列（合計時間 = N 件の合計）
const out: User[] = []
for (const id of ids) {
  out.push(await loadUser(id))
}

// ✅ 並列（合計時間 ≈ 最も遅い 1 件）
const out = await Promise.all(ids.map(loadUser))

async function safeLoad(id: string) {
  try {
    return await loadUser(id)
  } catch (e) {
    console.error('load failed', e)
    return null
  }
}

// グローバルキャッチ
window.addEventListener('unhandledrejection', (e) => {
  console.error('unhandled', e.reason)
})

// A
for (const id of ids) await loadUser(id)

// B
await Promise.all(ids.map(loadUser))

async function main() {
  loadUser('1')
  console.log('done')
}
main()
